Translate("deDE", "the-barrens", {
	title = "Brachland",
	aliases = { "Das Brachland" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Brachland ist eine weite Savanne aus gelbem Gras, Dornbäumen und rissiger roter Erde im Herzen von {link:kalimdor}Kalimdor{/link}. Es erstreckt sich von den Wäldern des {link:ashenvale}Eschentals{/link} im Norden bis zu den Schluchten von {link:thousand-needles}Tausend Nadeln{/link} im Süden und von den Klippen des {link:stonetalon-mountains}Steinkrallengebirges{/link} und {link:mulgore}Mulgore{/link} im Westen bis zur Küste des Großen Meeres im Osten. Nur wenige Orte der Welt sind so weit, so trocken oder so voller Leben, das beißt. Herden von Kodos und Zhevras durchziehen es, Löwen und Raptoren jagen darin, und ein Dutzend Völker kämpft um sein verstreutes Wasser. Jede Straße der {link:horde}Horde{/link} führt hindurch, und jeder Feind der Horde kennt es.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die Chronisten der Tauren sagen, das Brachland sei einst ein grünes und von Leben wimmelndes Land gewesen. Krieg und Katastrophe versengten es vor langer Zeit und ließen eine trockene Hülle zurück, und niemand, der heute lebt, erinnert sich an es anders. Die {link:tauren}Tauren{/link} durchstreiften seine Ebenen über Generationen, von einem Lager zum nächsten gejagt von den {link:centaurs}Zentauren{/link}. Die {link:quilboar}Stacheleber{/link} errichteten ihre Dornenbauten im Süden, und die {link:harpies}Harpyien{/link} nisteten auf seinen westlichen Hügeln.

Als die {link:orcs}Orcs{/link} nach dem {link:third-war}Dritten Krieg{/link} nach {link:kalimdor}Kalimdor{/link} kamen, führte {link:thrall}Thrall{/link} sie über diese Ebenen. Auf dem langen Marsch traf er {link:cairne-bloodhoof}Cairne Bloodhoof{/link} und sein Volk, das von Zentauren angegriffen wurde, und die Orcs schützten die Karawanen der Tauren, bis sie {link:mulgore}Mulgore{/link} erreichten. Nach dem Krieg am {link:mount-hyjal}Berg Hyjal{/link} machte die {link:horde}Horde{/link} das Brachland zur Straße zwischen ihren neuen Heimstätten: {link:orgrimmar}Orgrimmar{/link} und {link:durotar}Durotar{/link} im Osten, {link:thunder-bluff}Thunder Bluff{/link} im Westen.]=],
		},
		{
			title = "Die heutige Zeit",
			text = [=[Das Brachland gehört dem Namen nach der {link:horde}Horde{/link} und in Wahrheit dem, der in jedem Tal der Stärkste ist. {link:the-crossroads}Crossroads{/link}, eine befestigte Stadt der {link:orcs}Orcs{/link}, hält die Mitte. Die {link:tauren}Tauren{/link} von {link:camp-taurajo}Camp Taurajo{/link} bewachen den Süden. Goblins des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link} handeln im Hafen von {link:ratchet}Ratchet{/link} mit allen Seiten.

Feinde drängen von allen Seiten heran. Die {link:kolkar-centaurs}Kolkarzentauren{/link} haben neue Anführer gefunden. Die {link:razormane-quilboar}Stacheleber der Grimmhauer{/link} und der {link:bristleback-quilboar}Borstennacken{/link} führen Krieg gegen die Horde und gegeneinander. Soldaten aus {link:theramore-isle}Theramore{/link} halten die Feste {link:northwatch-hold}Northwatch{/link} an der Küste, {link:dwarves}Zwerge{/link} aus {link:ironforge}Ironforge{/link} graben in {link:bael-modan}Bael Modan{/link}, und die {link:venture-company}Venture Company{/link} vergiftet einen See im Norden. Kultisten der {link:burning-blade}Brennenden Klinge{/link} vollziehen ihre Riten auf dem {link:dreadmist-peak}Glutnebelgipfel{/link}. Am seltsamsten von allem ist, dass sich die Oasen zu verändern begonnen haben, und die Druiden fürchten, dass etwas unter dem Land träumt.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:horde}Horde{/link}.{/b} Grunzer der {link:orcs}Orcs{/link}, Krieger der {link:tauren}Tauren{/link}, Späher der {link:trolls}Trolle{/link} und einige Apotheker der {link:forsaken}Verlassenen{/link} halten die Posten und Straßen.
• {b}Die Goblins von {link:ratchet}Ratchet{/link}.{/b} Händler, Tüftler und Schläger, die an jeden verkaufen, der bezahlt.
• {b}Die {link:centaurs}Zentauren{/link}.{/b} Der {link:kolkar-centaurs}Stamm der Kolkar{/link} überfällt die Oasen und die Straßen.
• {b}Die {link:quilboar}Stacheleber{/link}.{/b} Die {link:razormane-quilboar}Grimmhauer{/link} halten den Norden und die südlichen Grate, die {link:bristleback-quilboar}Borstennacken{/link} die Mitte.
• {b}Die {link:alliance}Allianz{/link}.{/b} Die Marinesoldaten der Feste {link:northwatch-hold}Northwatch{/link} und die {link:dwarves}Zwerge{/link} von {link:bael-modan}Bael Modan{/link}.
• {b}Die {link:southsea-pirates}Südmeerfreibeuter{/link}.{/b} Piraten, die an der {link:the-merchant-coast}Händlerküste{/link} ihr Lager aufgeschlagen haben.
• {b}Die Bestien.{/b} Kodos, Zhevras, Ebenenschreiter, Savannenlöwen, Sonnenschuppenraptoren, Donnerechsen und Donnerfalken.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Das trockene Land.{/b} Lange bevor die {link:orcs}Orcs{/link} kamen, wurde das Brachland durch Krieg und Katastrophe verbrannt und ausgedörrt. Keine Chronik verzeichnet, wann.
• {b}Der lange Marsch.{/b} Thralls Orcs durchquerten die Ebenen, wehrten die {link:centaurs}Zentauren{/link} ab und brachten Cairnes Stämme sicher nach {link:mulgore}Mulgore{/link}.
• {b}Die Straße der {link:horde}Horde{/link}.{/b} Nach Hyjal errichteten die Orcs {link:the-crossroads}Crossroads{/link} und {link:morgan-s-vigil}die Wacht{/link}ürme der {link:gold-road}Goldstraße{/link}. Der Goblin {link:gazlowe}Gazlowe{/link} gründete {link:ratchet}Ratchet{/link} mit dem Gold, das er beim Bau von {link:orgrimmar}Orgrimmar{/link} verdient hatte.
• {b}Die heutige Zeit.{/b} Neue Oasen sprudeln aus der Erde hervor, und mit ihnen neue und verzerrte Geschöpfe.]=],
		},
		{
			title = "Überlieferungen der Ebenen",
			text = [=[• Die {link:tauren}Tauren{/link} geben den großen Bestien des Brachlands eigene Namen: Echeyakee, Weißnebel, ist der König der Savannenkatzen, und {link:lakota-windsong}Lakota{/link}'mani, Erderschütterer, ist der größte der Kodos.
• Die Sonnenschuppenraptoren des Brachlands sind klüger als ihre Artgenossen in anderen Landen. Einst stahlen sie das Silber, mit dem die Wachen von {link:the-crossroads}Crossroads{/link} bezahlt werden sollten, und noch hat niemand erklärt, warum.
• Ein gefangener {link:quilboar}Stacheleber{/link} in {link:camp-taurajo}Camp Taurajo{/link} wirkt noch immer die Magie Agamaggans. Er verkauft sie für Rache an dem Stamm, der ihn dort zurückließ.]=],
		},
	},
})

Translate("deDE", "the-crossroads", {
	title = "Crossroads",
	aliases = { "Crossroads" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Crossroads ist das Herz der {link:horde}Horde{/link} im {link:the-barrens}Brachland{/link}, eine ummauerte Stadt aus orcischen Hütten auf einem Hügel, an dem sich die großen Straßen treffen. Eine führt nach Norden zum {link:the-mor-shan-rampart}Mor'shan-Schutzwall{/link} und ins {link:ashenvale}Eschental{/link}, eine nach Osten nach {link:durotar}Durotar{/link} und {link:ratchet}Ratchet{/link}, eine nach Süden nach {link:camp-taurajo}Camp Taurajo{/link} und eine nach Westen zum {link:stonetalon-mountains}Steinkrallengebirge{/link} und nach {link:mulgore}Mulgore{/link}. {link:thork}Thork{/link} hütet ihre Mauern, {link:sergra-darkthorn}Sergra Darkthorn{/link} bildet ihre Jäger aus, und die Wachen auf ihrem Turm beobachten das Gras nach {link:centaurs}Zentauren{/link}. Ein {link:orcs}Orc{/link}, ein Druide der {link:tauren}Tauren{/link} und ein Apotheker der Verlassenen mögen hier dasselbe Feuer teilen, und die Windreiter von Devrak tragen Nachrichten nach {link:orgrimmar}Orgrimmar{/link}. In letzter Zeit haben Händler eines Unternehmens namens Versorgung und Logistik Durotar gleich westlich der Mauern einen Handelsposten errichtet.]=],
		},
	},
})

Translate("deDE", "camp-taurajo", {
	title = "Camp Taurajo",
	aliases = { "Taurajo" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Camp Taurajo ist die Festung der {link:tauren}Tauren{/link} im südlichen {link:the-barrens}Brachland{/link}, ein Ring aus Zelten und Totems an der Straße nach {link:thousand-needles}Tausend Nadeln{/link}. Es bewacht die Ebenen, die nach {link:mulgore}Mulgore{/link} führen, und seine Krieger reiten gegen die Lager der {link:quilboar}Stacheleber{/link} auf allen Seiten aus. Der Jäger {link:jorn-skyseer}Jorn Skyseer{/link} lehrt hier, der Schmied {link:tatternack-steelforge}Tatternack Steelforge{/link} studiert die Waffen des Feindes, und in einem Käfig am Rand des Lagers sitzt {link:mangletooth}Mangletooth{/link}, ein Stacheleber, den sein eigener Stamm verrotten ließ. Grunzer Logmar hat kürzlich gehört, dass menschliche Soldaten aus den {link:dustwallow-marsh}Marschen von Dustwallow{/link} an der Ostgrenze die Wegmarken der Pfadfinder der Tauren umstürzen.]=],
		},
	},
})

Translate("deDE", "ratchet", {
	title = "Ratchet",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ratchet ist ein Goblinhafen an der Ostküste des Brachlands, am Rand der {link:the-merchant-coast}Händlerküste{/link}. Der Goblin {link:gazlowe}Gazlowe{/link} erbaute ihn mit dem Gold, das er beim Bau von {link:orgrimmar}Orgrimmar{/link} verdient hatte, und er gehört dem {link:steamwheedle-cartel}Steamwheedle-Kartell{/link}. Hier können {link:orcs}Orc{/link} und Mensch Seite an Seite kaufen und verkaufen, denn die Schläger der Stadt wahren den Frieden mit harter Hand. Schiffe segeln von seinen Docks über das Meer nach {link:booty-bay}Booty Bay{/link}. Seine Tüftler bauen Schredder, seine Brauer bewahren alte Rezepte, und seine Händler jagen jedem Gerücht von Gewinn nach, vom {link:the-sludge-fen}Schlickermoor{/link} bis zu den {link:wailing-caverns}Höhlen des Wehklagens{/link}. Piraten und Haie sind seine einzigen wahren Feinde, und davon hat es reichlich.]=],
		},
	},
})

Translate("deDE", "northwatch-hold", {
	title = "Die Feste Northwatch",
	aliases = { "Northwatch" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Feste Northwatch ist eine steinerne Festung der {link:alliance}Allianz{/link} auf einem Hügel über der südlichen {link:the-merchant-coast}Händlerküste{/link}. {link:humans}Menschen{/link} errichteten sie nach dem Krieg am {link:mount-hyjal}Berg Hyjal{/link}, und Admiral {link:daelin-proudmoore}Daelin Proudmoore{/link} bediente sich ihrer in seinem Krieg gegen die {link:horde}Horde{/link}. Heute wird sie von Soldaten aus {link:theramore-isle}Theramore{/link} unter {link:captain-fairmount}Hauptmann Fairmount{/link} gehalten. Ihre Marinesoldaten sind nervös und schießen schnell. Ihre Kanonen haben mehr als ein Schiff mit Kurs auf {link:ratchet}Ratchet{/link} versenkt, und sie halten Gefangene, die sie Bedrohungen für die Allianz nennen, manche von ihnen nicht mehr als Deckmatrosen. Für die {link:orcs}Orcs{/link} sind ihre Mauern ein Speer, der auf das Herz des Brachlands zielt.]=],
		},
	},
})

Translate("deDE", "far-watch-post", {
	title = "Farwatch-Posten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Farwatch-Posten steht am Ostrand des Brachlands, nahe der Brücke, die über den Südstrom nach {link:durotar}Durotar{/link} führt. Er ist ein kleines Lager der {link:orcs}Orcs{/link} mit einem Wachturm und einigen Katapulten, und er ist der erste Posten, den neue Rekruten erreichen, wenn sie die Heimat der Orcs verlassen. Kargal Battlescar unterzeichnet ihre Papiere und schickt sie weiter nach {link:the-crossroads}Crossroads{/link}. Der Krieger Uzzek prüft hier die jungen Kämpfer der {link:horde}Horde{/link}, und Ak'Zeloth, ein Agent des Hexenmeisters {link:neeru-fireblade}Neeru Fireblade{/link}, bereitet Steine der Macht gegen die Dämonen des Glutnebelgipfels vor.]=],
		},
	},
})

Translate("deDE", "the-mor-shan-rampart", {
	title = "Der Mor'shan-Schutzwall",
	aliases = { "Mor'shan-Schutzwall", "Mor'shan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Mor'shan-Schutzwall ist ein Wall aus Holz und Stein am nördlichen Ende der {link:gold-road}Goldstraße{/link}, wo das Gras des Brachlands auf die Bäume des {link:ashenvale}Eschentals{/link} trifft. Er ist das Tor zum Krieg der {link:horde}Horde{/link} im Wald. Die {link:orcs}Orcs{/link} der Warsong schlagen Holz im Eschental, und die {link:night-elves}Nachtelfen{/link} beantworten jede Axt mit Pfeilen. Vom Wachturm des Schutzwalls aus lenkt Kadrak den Feldzug im Eschental. Er schickt Läufer zu den neuen Außenposten am {link:the-zoram-strand}Zoramstrand{/link} und zum {link:splintertree-post}Splintertreeposten{/link}, und er bringt ihre Berichte heim.]=],
		},
	},
})

Translate("deDE", "lushwater-oasis", {
	title = "Die blühende Oase",
	aliases = { "Blühende Oase" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die blühende Oase liegt südlich von {link:the-crossroads}Crossroads{/link}, eine Ansammlung von Palmen und Teichen im trockenen Gras. Sie ist eine der neuen Oasen, die in den letzten Jahren unter dem {link:the-barrens}Brachland{/link} hervorgesprudelt sind. An ihrer Nordseite erhebt sich ein felsiger Hügel, und in dem Hügel öffnet sich der Eingang der {link:wailing-caverns}Höhlen des Wehklagens{/link}, aus dem der Wind Tag und Nacht stöhnt. Die {link:kolkar-centaurs}Kolkarzentauren{/link} von {link:hezrul-bloodmark}Hezrul Bloodmark{/link} lagern um das Wasser. Zwei Schüler des Druiden {link:naralex}Naralex{/link} halten auf dem Hügel über den Höhlen Wache, und die Tiere, die hier trinken, beginnen seltsam zu werden.]=],
		},
	},
})

Translate("deDE", "the-stagnant-oasis", {
	title = "Die brackige Oase",
	aliases = { "Brackige Oase" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die brackige Oase liegt südöstlich von {link:the-crossroads}Crossroads{/link}, ein stiller und trüber Teich inmitten des Graslands. Die {link:kolkar-centaurs}Kolkarzentauren{/link} haben an ihrem Ufer ein Kommandozelt errichtet, und der Derwisch {link:verog-the-dervish}Verog{/link} kommt dorthin, wenn sein Stamm ihn ruft. Ein Spalt in der Erde unter dem Wasser birgt eine seltsame Macht. Trockene und tote Samen, die hineinfielen, erwachten zum Leben. Die Schnappkieferschildkröten des Teichs tragen in ihren Panzern einen Makel, den noch kein Druide gesehen hat. Südlich der Oase haben die Sonnenschuppenraptoren ihre Nester.]=],
		},
	},
})

Translate("deDE", "the-forgotten-pools", {
	title = "Die vergessenen Teiche",
	aliases = { "Vergessene Teiche" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die vergessenen Teiche liegen nordwestlich von {link:the-crossroads}Crossroads{/link}, nördlich der westlichen Straße. Sie sind die nördlichsten der Oasen des Brachlands. Ein Spalt in der Erde öffnet sich unter ihren Wassern, und aus ihm steigen ohne Ende Gase auf. Hier fand der Druide {link:tonga-runetotem}Tonga Runetotem{/link} zuerst ein Zeichen der Macht, die in das Land sickert. Die {link:kolkar-centaurs}Kolkarzentauren{/link} streifen um die Teiche, und ihr Häuptling {link:barak-kodobane}Barak Kodobane{/link} hat sein Lager in der Nähe aufgeschlagen.]=],
		},
	},
})

Translate("deDE", "field-of-giants", {
	title = "Feld der Riesen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Feld der Riesen bedeckt die südlichen Ebenen des Brachlands, zwischen {link:camp-taurajo}Camp Taurajo{/link} und der Grenze zu den {link:dustwallow-marsh}Marschen von Dustwallow{/link}. Große Türme aus getrockneter Erde erheben sich aus dem Gras, und aus der Ferne sehen sie aus wie Riesen, die reglos dastehen. Donnerechsen und Kodos grasen zwischen ihnen. In letzter Zeit sind auf dem Feld insektenartige Geschöpfe aufgetaucht, die man Sillithid nennt. Sie graben Stöcke, legen Eier und scheinen auf eine Weise zu denken, wie es keine Bestie tun sollte. Korran aus {link:the-crossroads}Crossroads{/link} studiert sie für seine Herren in {link:orgrimmar}Orgrimmar{/link}, und der Jäger {link:jorn-skyseer}Jorn Skyseer{/link} fürchtet, dass sie eine düstere Zukunft ankündigen.]=],
		},
	},
})

Translate("deDE", "bael-modan", {
	title = "Bael Modan",
	aliases = { "Burg Bael'dun" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bael Modan ist eine Grabungsstätte der {link:dwarves}Zwerge{/link} im äußersten Süden des Brachlands, bewacht von den Steinmauern der Burg Bael'dun. Die Zwerge sprengen tiefe Löcher in die Erde, und ihre Maschinen reißen an den Hügeln. Ihre Flugmaschine kreist über ihnen. Das Land, in dem sie graben, war einst die Heimat der {link:tauren}Tauren{/link} der Stonespire, und es war ihnen heilig. Der Stamm wurde vertrieben, und nur der Wanderer {link:gann-stonespire}Gann Stonespire{/link} zieht noch über die nahen Straßen und sinnt auf Rache. Der erste große Fund der Grabung war ein Stein, den man die Träne der Monde nennt. Der General der Zwerge schloss ihn als verflucht weg.]=],
		},
	},
})

Translate("deDE", "dreadmist-peak", {
	title = "Glutnebelgipfel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Glutnebelgipfel erhebt sich nordwestlich von {link:the-crossroads}Crossroads{/link}, sein Gipfel in einen roten Nebel gehüllt. Die Kultisten der {link:burning-blade}Brennenden Klinge{/link} halten seine Höhen. In einer Höhle nahe der Spitze, über einem Altar aus Feuer, verwahren sie den Dämonensamen, ein Werkzeug der {link:burning-legion}Brennenden Legion{/link}. Die Teiche auf dem Gipfel speisen das Wetter der nördlichen Ebenen, und die Druiden fürchten, dass der Kult sie vergiftet hat und dass die Krankheit, die sich unter den Gazellen der Ebenen ausbreitet, dort beginnt. Selbst {link:neeru-fireblade}Neeru Fireblade{/link} aus {link:orgrimmar}Orgrimmar{/link} hat darum gebeten, den Samen zu zerstören. Es heißt, in den Jahren nach dem Dritten Krieg habe {link:jaina-proudmoore}Jaina Proudmoore{/link} selbst auf diesem Gipfel gegen einen Dämon gekämpft.]=],
		},
	},
})

Translate("deDE", "blackthorn-ridge", {
	title = "Schwarzdorngrat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Schwarzdorngrat ist ein dorniges Tal im Süden des Brachlands, nördlich des großen Baus, {link:razorfen-kraul}des Krals von Razorfen{/link}. Die {link:razormane-quilboar}Stacheleber der Grimmhauer{/link} halten es. Drei Häuptlinge sind aus dem Kral heraufgestiegen, um ihren Krieg gegen die {link:horde}Horde{/link} zu befehligen: {link:nak}Nak{/link} der Seher, Kuz der Fährtenleser und {link:lok-orcbane}Lok Orcbane{/link}, ihr Kriegsherr. Ihre Lager liegen zwischen den Dornen. Auf dem Grat über dem Tal unterhält der orcische Schamane Brine ein einsames Lager neben einem Teich reinen Wassers und lehrt die jungen Schamanen der Horde den Ruf des Wassers.]=],
		},
	},
})

Translate("deDE", "honor-s-stand", {
	title = "Ehrenmal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Ehrenmal liegt an der westlichen Straße des Brachlands, wo sie zum {link:stonetalon-mountains}Steinkrallengebirge{/link} ansteigt. Keine Chronik verzeichnet, wer ihm den Namen gab oder an welches Standhalten es erinnert. Zwei Reisende der {link:horde}Horde{/link} lagern hier an der Straße. {link:seereth-stonebreak}Seereth Stonebreak{/link} ist ein Schamane, der die Geister des Steinkrallengebirges gegen die {link:venture-company}Venture Company{/link} aufschreien hört. {link:makaba-flathoof}Makaba Flathoof{/link} ist ein {link:tauren}Tauren{/link}, dessen Dorf von den Grimmtotem niedergebrannt wurde und der nur noch mehr von ihnen tot sehen will.]=],
		},
	},
})

Translate("deDE", "the-merchant-coast", {
	title = "Die Händlerküste",
	aliases = { "Händlerküste" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Händlerküste ist die Ostküste des Brachlands, von {link:ratchet}Ratchet{/link} im Norden bis zu den Mauern der Feste {link:northwatch-hold}Northwatch{/link} im Süden. Sie hat ihren Namen von dem Handel, der durch den Goblinhafen fließt. Südlich von Ratchet haben die Piraten der {link:southsea-pirates}Südmeerfreibeuter{/link} Lager am Strand errichtet. Sie überfallen die Schiffe von {link:gazlowe}Gazlowe{/link} und der Handelsprinzen, und sie gehorchen {link:baron-longshore}Baron Longshore{/link}, dem Kapitän der Heedless. Ein Tüftler aus Ratchet schickte einmal eine Maschine gegen sie. Sie kam nie heim. Ihre Teile liegen nun über das Lager der Piraten verstreut.]=],
		},
	},
})

Translate("deDE", "boulder-lode-mine", {
	title = "Felsadermine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Felsadermine liegt im äußersten Nordosten des Brachlands, jenseits des Schlickermoors. Orcische Balken stützen noch ihre Stollen, doch die {link:venture-company}Venture Company{/link} hat sie in Besitz genommen. Nachrichten verbreiten sich schnell bis {link:ratchet}Ratchet{/link}, und die neueste besagt, dass einer der Goblinbergleute einen Smaragd so groß wie eine Faust ausgegraben hat. Der Hafenmeister von Ratchet kennt Käufer, die gut dafür bezahlen würden, und er ist nicht der Einzige, der davon gehört hat.]=],
		},
	},
})

Translate("deDE", "thorn-hill", {
	title = "Dornenhügel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Dornenhügel erhebt sich östlich von {link:the-crossroads}Crossroads{/link}, zwischen der Stadt und der Straße nach {link:durotar}Durotar{/link}. Seine Hänge sind von den großen Dornenranken der {link:razormane-quilboar}Grimmhauer{/link} umschlungen. Von hier aus fiel der Plünderer {link:kreenig-snarlsnout}Kreenig Snarlsnout{/link} über die Karawanen aus Durotar her und mästete sich an den Vorräten der {link:horde}Horde{/link}. Schlimmeres lauert in einer Höhle auf dem Plateau. Die {link:quilboar}Stacheleber{/link} sprechen von {link:chol-aruk}Chol'aruk{/link}, dem Verschlinger, einer ungeheuerlichen Bestie ihrer eigenen Art, an die niemand glaubte, bis Krieger hineingingen, um sie zu finden.]=],
		},
	},
})

Translate("deDE", "raptor-grounds", {
	title = "Raptorgründe",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Raptorgründe sind ein kleines Tal südlich von {link:ratchet}Ratchet{/link} und westlich der Feste {link:northwatch-hold}Northwatch{/link}. Die Sonnenschuppenraptoren haben hier ihre Nester, und sie sind klüger, als Raptoren es sein dürften. Sie stahlen eine Silberlieferung aus dem Wachturm von {link:the-crossroads}Crossroads{/link}, den Sold seiner Soldaten, und trugen sie zu ihren Nestern zurück. Niemand weiß, was ein Raptor mit Silber will. Der Goblin Mebok Mizzyrix glaubt, dass ihre Schläue in ihren Hörnern liegt.]=],
		},
	},
})

Translate("deDE", "the-sludge-fen", {
	title = "Das Schlickermoor",
	aliases = { "Schlickermoor" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Schlickermoor liegt im Nordosten des Brachlands. Die {link:venture-company}Venture Company{/link} hat einen Ölbohrturm darüber errichtet, und was ein Wasserteich war, ist nun ein Sumpf aus schwarzem Schlick. Aufseher Lugwizzle leitet die Arbeiten von der Spitze des Bohrturms aus, und Goblinschredder staksen am Ufer umher. Die Tüftler von {link:ratchet}Ratchet{/link} beneiden das Unternehmen um seine neuen Maschinen. Einer von ihnen, Wizzlecrank, schlich sich hinein, um einen Schredder zu stehlen, und merkte zu spät, dass er keinen Schlüssel hatte, um ihn zum Laufen zu bringen.]=],
		},
	},
})

Translate("deDE", "agama-gor", {
	title = "Agama'gor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Agama'gor ist ein Lager der {link:quilboar}Stacheleber{/link} der {link:bristleback-quilboar}Borstennacken{/link} in der Mitte des Brachlands, nördlich der Straße, die von {link:camp-taurajo}Camp Taurajo{/link} nach Westen führt. Seine Geomanten graben blutrote Steine aus der Erde, die die Stacheleber als Totems der Stärke tragen. Grunzer aus Camp Taurajo haben hier gekämpft und sind nicht immer heimgekehrt. Einer von ihnen, Grunzer Dogran, lag verwundet nahe dem Lager, während seine Kameraden nach Heilung schickten. Jenseits der Straße beobachten die {link:razormane-quilboar}Grimmhauer{/link} der {link:bramblescar}Dornennarbe{/link} die Borstennacken voller Hass.]=],
		},
	},
})

Translate("deDE", "bramblescar", {
	title = "Dornennarbe",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Dornennarbe ist ein Dornenlager der {link:razormane-quilboar}Grimmhauer{/link} in der Mitte des Brachlands, östlich der Straße zwischen {link:the-crossroads}Crossroads{/link} und {link:camp-taurajo}Camp Taurajo{/link}. Die Grimmhauer hier liegen im Krieg mit den {link:bristleback-quilboar}Borstennacken{/link} von {link:agama-gor}Agama'gor{/link} jenseits der Straße, und sie greifen jeden anderen an, der in die Nähe kommt. Ganz in der Nähe, in einem kleinen Lager der {link:tauren}Tauren{/link}, kämpften der {link:orcs}Orc{/link} {link:mankrik}Mankrik{/link} und seine Frau ihre letzte Schlacht gemeinsam. Mankrik glaubt, dass die Plünderer der Grimmhauer aus dieser Gegend die Knochenjuwelen fortschleppten, die sie trug.]=],
		},
	},
})

Translate("deDE", "gold-road", {
	title = "Goldstraße",
	aliases = { "Südliche Goldstraße", "die Goldstraße" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Goldstraße ist die große Fernstraße des Brachlands. Sie führt vom {link:the-mor-shan-rampart}Mor'shan-Schutzwall{/link} im Norden über {link:the-crossroads}Crossroads{/link} und {link:camp-taurajo}Camp Taurajo{/link} bis zum großen Aufzug am Rand von {link:thousand-needles}Tausend Nadeln{/link} im Süden. Sie hat ihren Namen von den Handelskarawanen, die auf ihr reisen. Ihr nördlicher Abschnitt wird von Türmen der {link:horde}Horde{/link} bewacht. Ihr südlicher Abschnitt ist einsamer, und ein Wanderer, der in der Dämmerung von ihr abkommt, findet sich womöglich auf einem Baum wieder, während unter ihm Hyänen kreisen.]=],
		},
	},
})

Translate("deDE", "the-dry-hills", {
	title = "Die trockenen Hügel",
	aliases = { "Trockene Hügel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die trockenen Hügel erheben sich im äußersten Nordwesten des Brachlands, die grünen Ausläufer des Steinkrallengebirges. Die {link:harpies}Harpyien{/link} der Witchwing nisten hier unter Serena Bloodfeather und stoßen auf die Karawanen der nördlichen Straße herab. Auf einem Grat über den Hügeln lebt ein einsiedlerischer Gerber namens {link:walton}Walton{/link}, der keine Gesellschaft will. Der Jäger {link:vrang-wildgore}Vrang Wildgore{/link} stellt im Tal darunter seine Fallen auf. In letzter Zeit hat man Männer in der Livree von {link:kul-tiras}Kul Tiras{/link} gesehen, die dieses Tal absuchten und neben einer zerstörten Karawane lagerten.]=],
		},
	},
})

Translate("deDE", "grol-dom-farm", {
	title = "Grol'doms Hof",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grol'doms Hof ist ein Schweinehof der {link:orcs}Orcs{/link} an der Straße zwischen {link:the-crossroads}Crossroads{/link} und {link:durotar}Durotar{/link}, einer der vielen, die seit der Gründung von {link:orgrimmar}Orgrimmar{/link} entstanden sind. Er ist ein ruhiger Ort voller Pferche und Schweine. Sein Herr, Kranal Fiss, ist ein Schamane der {link:horde}Horde{/link}. Er schickt jene, die das Feuer zähmen wollen, zu einem verborgenen Schrein in Durotar und bittet sie, ihm die Fackel brennend zurückzubringen.]=],
		},
	},
})

Translate("deDE", "fray-island", {
	title = "Prügel-Eiland",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Prügel-Eiland ist eine kleine, trockene Insel vor der Ostküste des Brachlands. Ihr Herr, Klannoc Macleod, nennt sich den Insulaner, und er betreibt einen Übungsplatz für Krieger aller Völker. Wer von ihm lernen will, muss zuerst die Rauferei bestehen: Er tritt mitten in eine Menge und kämpft gegen einen Herausforderer nach dem anderen, bis der Champion herauskommt, um sich ihm zu stellen.]=],
		},
	},
})

Translate("deDE", "thork", {
	title = "Thork",
	subtitle = "Hüter von Crossroads",
	found = "Crossroads, oben auf dem Hügel der Stadt",
	hint = "Sprich mit dem Orc, der Crossroads hütet.",
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thork hütet {link:the-crossroads}Crossroads{/link} für die {link:horde}Horde{/link}. Jeder Neuankömmling im {link:the-barrens}Brachland{/link} wird zu ihm geschickt, sei es ein {link:orcs}Orc{/link} aus {link:durotar}Durotar{/link}, ein {link:tauren}Tauren{/link} aus {link:thunder-bluff}Thunder Bluff{/link} oder ein Fremder, den der Kriegshäuptling selbst gesandt hat. Er begrüßt sie barsch, schätzt sie ab und stellt sie an die Arbeit. Seine größte Sorge ist die Straße nach Durotar, wo die {link:razormane-quilboar}Grimmhauer{/link} über die Karawanen herfallen, die seine Stadt versorgen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thork ist die erste Stimme der Ordnung der {link:horde}Horde{/link} im {link:the-barrens}Brachland{/link}. Die Seher der {link:tauren}Tauren{/link} sagen, er habe den Segen der Erdenmutter.]=],
		},
		{
			title = "Taten",
			text = [=[• Er jagt die Plünderer der {link:razormane-quilboar}Grimmhauer{/link}, die die Versorgungswege aus {link:durotar}Durotar{/link} angreifen.
• Er schickt Freiwillige nach Norden zu Kadrak und in den Krieg im {link:ashenvale}Eschental{/link}.
• Er hieß die {link:skyborne}Skyborne{/link} willkommen, die der Kriegshäuptling nach {link:the-crossroads}Crossroads{/link} gesandt hatte.]=],
		},
	},
	mentions = {
		{
			text = [=[Reise nach {link:the-crossroads}Crossroads{/link}, von {link:camp-taurajo}Camp Taurajo{/link} aus]=],
		},
		{ text = "Unterbrecht die Angriffe" },
		{ text = "Das Ende der Störungen" },
		{ text = "Vorräte für {link:the-crossroads}Crossroads{/link}" },
		{
			text = [=[Verrat von innen, der Kopf von {link:lok-orcbane}Lok Orcbane{/link}]=],
		},
		{ text = "Meldet Euch bei Kadrak" },
		{
			text = [=[Reise nach {link:the-crossroads}Crossroads{/link}, von {link:thrall}Thrall{/link} gesandt]=],
		},
	},
	bonds = {
		{ id = "kreenig-snarlsnout", name = "Kreenig Snarlsnout", note = "sein Feind" },
		{ id = "lok-orcbane", name = "Lok Orcbane", note = "der wahre Anführer der Überfälle" },
		{ id = "mangletooth", name = "Mangletooth", note = "würde bei ihm keinen Glauben finden" },
		{ id = "thrall", name = "Thrall", note = "schickt ihm neue Rekruten" },
	},
})

Translate("deDE", "sergra-darkthorn", {
	title = "Sergra Darkthorn",
	subtitle = "Jagdmeisterin von Crossroads",
	found = "Crossroads",
	hint = [=[Sprich mit der Orcfrau, die die Jungen auf den Pfad des Jägers führt.]=],
	allegiance = "Horde",
	aliases = { "Sergra" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sergra Darkthorn führt die Jungen der {link:horde}Horde{/link} im {link:the-barrens}Brachland{/link} auf den Pfad des Jägers. Sie schickt sie zuerst gegen Ebenenschreiter und Zhevras, dann gegen Pirscher und Raptoren und schließlich gegen Echeyakee, den weißen Löwen. Sie duldet keine Frechheit. Der Kriegshäuptling hat die Frauen der Horde den Männern gleichgestellt, und sie verlangt, so behandelt zu werden. Manche ihrer eigenen Kameraden nennen sie hart, doch sie bittet ihre Jäger, die Leben zu bedenken, die sie nehmen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Sergra gehört zu jenen, von denen {link:thrall}Thrall{/link} glaubt, sie seien etwas Besonderes. Jeder Jäger, der weiter nach {link:camp-taurajo}Camp Taurajo{/link} zieht, wurde zuerst von ihr geprüft.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie jagt die Bestien, die die Versorgungsketten von {link:the-crossroads}Crossroads{/link} bedrohen.
• Sie schickt Jäger gegen Echeyakee, den König der Savannenkatzen.
• Sie gibt ihre besten Schüler an {link:jorn-skyseer}Jorn Skyseer{/link} weiter.]=],
		},
	},
	mentions = {
		{ text = "Einberufung in {link:the-crossroads}Crossroads{/link}" },
		{ text = "Sergra Darkthorn" },
		{ text = "Die Ebenenschreiterplage" },
		{ text = "Die Zhevras" },
		{ text = "Pirscher des Brachlands" },
		{ text = "Echeyakee" },
		{ text = "Die wütenden Sichelklauen" },
		{ text = "{link:jorn-skyseer}Jorn Skyseer{/link}" },
	},
	bonds = {
		{ id = "jorn-skyseer", name = "Jorn Skyseer", note = "setzt ihre Lehre fort" },
		{ id = "thrall", name = "Thrall", note = "glaubt an sie" },
	},
})

Translate("deDE", "apothecary-helbrim", {
	title = "Apotheker Helbrim",
	subtitle = "Apotheker von Crossroads",
	found = "Crossroads",
	hint = [=[Sprich mit dem Apotheker der Verlassenen, der in Crossroads arbeitet.]=],
	allegiance = "Königliche Apothekervereinigung · Verlassene",
	aliases = { "Helbrim" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Apotheker Helbrim ist einer der {link:forsaken}Verlassenen{/link} der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link}, fern von {link:lordaeron}Lordaeron{/link} entsandt, um in {link:the-crossroads}Crossroads{/link} zu arbeiten. Er studiert, was die Gifte seiner Heimat bei den Bestien Kalimdors bewirken. Zudem ziehen ihn die Oasen an, deren Wasser jede Pflanze und jedes Geschöpf verändert, das davon trinkt. Die Verlassenen halten ihre Verträge ein, sagt er, und er bezahlt jene, die ihm bringen, was er braucht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Helbrim ist die Gegenwart der Verlassenen in den Ebenen, ein stilles Zeichen des Pakts zwischen den Toten und der {link:horde}Horde{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelt Pilzsporen aus den Oasen und verarbeitet sie zu einer Emulsion.
• Er schickt seine Arbeit an Apotheker {link:apothecary-zamah}Zamah{/link} in {link:thunder-bluff}Thunder Bluff{/link}.
• Er verschifft Kisten mit Tränken und Reagenzien an seine Kollegen jenseits des Meeres.]=],
		},
	},
	mentions = {
		{ text = "Pilzsporen" },
		{ text = "Apotheker {link:apothecary-zamah}Zamah{/link}" },
		{ text = "Hafenmeister Dizzywig" },
		{ text = "Eine Probe für Helbrim" },
	},
	bonds = {
		{ id = "apothecary-zamah", name = "Apotheker Zamah", note = "sein Partner" },
	},
})

Translate("deDE", "gazlowe", {
	title = "Gazlowe",
	subtitle = "Herr von Ratchet",
	found = "Ratchet",
	hint = "Sprich mit dem Goblin, der den Hafen von Ratchet führt.",
	allegiance = "Steamwheedle-Kartell · Ratchet",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gazlowe ist der Goblin, der {link:ratchet}Ratchet{/link} gründete und es noch immer führt. Er ist Baumeister von Beruf und Händler von Natur. Als die {link:orcs}Orcs{/link} nach {link:kalimdor}Kalimdor{/link} kamen, stellte {link:thrall}Thrall{/link} ihn als obersten Ingenieur der neuen Nation {link:durotar}Durotar{/link} ein, und seine Trupps halfen, die Mauern von {link:orgrimmar}Orgrimmar{/link} zu errichten. Thrall bezahlte ihn gut. Mit diesem Gold baute Gazlowe einen eigenen Hafen an der Mündung des Südstroms, wo jeder handeln darf, solange er bezahlt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gazlowe ist der älteste Goblinfreund der {link:horde}Horde{/link}. Sein Hafen ist neutraler Boden, auch der {link:alliance}Allianz{/link} offen, doch sein Wohlwollen gegenüber den {link:orcs}Orcs{/link} ist wohlbekannt. Durch {link:ratchet}Ratchet{/link} fließt vieles von dem, was die Horde jenseits des Meeres kauft.]=],
		},
		{
			title = "Taten",
			text = [=[• Er diente in den Jahren ihrer Gründung als oberster Ingenieur von {link:durotar}Durotar{/link}.
• Er gründete {link:ratchet}Ratchet{/link} als Hafen des {link:steamwheedle-cartel}Steamwheedle-Kartells{/link}.
• Er schickte seinen Mann {link:rezlak}Rezlak{/link}, um den {link:orcs}Orcs{/link} in Durotar weiterhin zu helfen.
• Er unterstützt die Goblinrennfahrer von {link:thousand-needles}Tausend Nadeln{/link} und spürt Teile für ihre Maschinen auf.
• Er hat in Ratchet ein Observatorium gebaut und wartet auf dessen Linsen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Über Gazlowes Leben vor {link:durotar}Durotar{/link} ist hier wenig geschrieben. Dieser Eintrag verzeichnet nur, was seine Taten und sein Hafen offenbaren.]=],
		},
	},
	chapters = {
		{
			title = "Die Freibeuter",
			hint = "Vertreibe die Piraten von der Küste südlich von Ratchet.",
			text = [=[Die Handelsprinzen stecken Gold in ihre Flotten, und dennoch überfallen die Piraten der {link:southsea-pirates}Südmeerfreibeuter{/link} seine Schiffe. Gazlowe murrt, dass der Admiral der Flotten zu wenig tue. Als die Piraten seine Waren raubten, darunter eine Linse für sein Observatorium und eine Kiste Stiefel aus {link:booty-bay}Booty Bay{/link}, heuerte er andere an, sie zurückzuholen.]=],
		},
		{
			title = "Der Kapitän der Heedless",
			hint = "Fordere das Kopfgeld auf den Piratenbaron ein.",
			text = [=[Gazlowe setzte ein Kopfgeld auf {link:baron-longshore}Baron Longshore{/link} aus, den Gilneer, der die Freibeuter anführt, und verlangte seine Überreste in einem Zustand, in dem er sie erkennen könne. Als die Tat vollbracht war, gab er zu, dass er einst das Schiff des Barons über die offene See hatte gleiten sehen und es für einen schönen Anblick gehalten hatte.]=],
		},
		{
			title = "Der Hai",
			hint = "Folge dem Aufruf an die Angler, der in Ratchet aushängt.",
			text = [=[Ein großer Hai begann, in den Gewässern am Dock zu kreisen und Seeleute und kleine Boote anzugreifen. Die Hafenarbeiter nannten ihn Bruuz, und bald wollte keine Mannschaft mehr ins Wasser. Gazlowe setzte eine Belohnung für seine Flosse aus. Als die Flosse kam, sagte er, er werde sie vielleicht in seine Suppe tun, um zuletzt zu lachen.]=],
		},
	},
	mentions = {
		{ text = "Die verschollene Lieferung" },
		{ text = "Die verschollene Lieferung, Dizzywigs Antwort" },
		{ text = "Goblinsponsoring" },
		{ text = "Goblinsponsoring, der verlorene Treibstoffregler" },
		{ text = "Ärger an den Docks, ein Geschenk alten Portweins" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "stellte ihn ein, um Durotar zu bauen" },
		{ id = "rezlak", name = "Rezlak", note = "sein Mann in Durotar" },
		{ id = "baron-longshore", name = "Baron Longshore", note = "der Pirat, den er tot sehen wollte" },
		{ id = "innkeeper-wiley", name = "Gastwirt Wiley", note = "führt das Gasthaus seines Hafens" },
	},
})

Translate("deDE", "innkeeper-wiley", {
	title = "Gastwirt Wiley",
	subtitle = "Gastwirt von Ratchet",
	found = "Das Gasthaus von Ratchet",
	hint = "Sprich mit dem Gastwirt von Ratchet.",
	allegiance = "Ratchet",
	aliases = { "Wiley" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gastwirt Wiley führt das Gasthaus von {link:ratchet}Ratchet{/link}, wo Seeleute, Händler und Soldaten beider Fraktionen unter einem Dach sitzen. Er schenkt {link:orcs}Orc{/link} und Mensch gleichermaßen ein und stellt wenige Fragen. In Ratchet heißt es, er führe Buch über die Taten derer, die unter seinem Dach verweilen, und Ehren kämen zu jenen, deren Namen er aufschreibt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wileys Gasthaus ist der neutrale Herd des Brachlands, wo Neuigkeiten von jeder Straße früher oder später ankommen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führt das Gasthaus von {link:ratchet}Ratchet{/link} und seine Schankstube.
• Er verkauft Speise und Trank an alle, die in Frieden kommen.]=],
		},
	},
	bonds = {
		{ id = "gazlowe", name = "Gazlowe", note = "Herr des Hafens" },
	},
})

Translate("deDE", "mankrik", {
	title = "Mankrik",
	subtitle = "Der trauernde Krieger",
	found = "Crossroads",
	hint = [=[Sprich mit dem Orc, der von Crossroads aus den Horizont beobachtet.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mankrik ist ein orcischer Krieger aus {link:the-crossroads}Crossroads{/link}. Er und seine Frau kämpften an der Seite der {link:tauren}Tauren{/link} in einem kleinen Lager, als die {link:quilboar}Stacheleber{/link} sie überrannten. Sie hielt drei von ihnen allein auf. Er führte andere fort, und als er sich umwandte, sah er sie fallen. Dann brachten sie ihn zu Boden. Ein Druide der Tauren fand ihn auf der {link:gold-road}Goldstraße{/link} und versorgte seine Wunden. Nun steht er von der Morgendämmerung bis zur Abenddämmerung in Crossroads, starrt auf den Horizont, und er hat seither jeden Stacheleber getötet, dem er begegnet ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mankriks Trauer kennt jeder, der durch {link:the-crossroads}Crossroads{/link} kommt. Für viele ist er der Beweis dafür, was der Krieg mit den Stachelebern kostet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hat den Stachelebern, die ihm seine Frau nahmen, Rache geschworen.
• Er verlangt die Hauer der {link:bristleback-quilboar}Borstennacken{/link}, um ihren Tod zu feiern.
• Er errichtet ihr ein Denkmal.]=],
		},
	},
	chapters = {
		{
			title = "In der Schlacht verloren",
			hint = "Suche nach Mankriks Frau.",
			text = [=[Mankrik bat nur um irgendein Zeichen von ihr. Man fand sie dort, wo die Kämpfe gewesen waren, und sie war tot. Er nahm die Nachricht schweigend auf. Dann kehrte er zu seiner Wache zurück.]=],
		},
		{
			title = "Ihr Name ist Olgra",
			hint = "Birg den Schmuck von Mankriks Frau.",
			text = [=[Der Heiler, der Mankrik rettete, konnte sie nicht retten. Ihr Name war {link:olgra}Olgra{/link}. Sie hatte viele Juwelen aus poliertem Knochen getragen, ihre eigenen Kunstwerke, und sie waren von ihrem Leichnam verschwunden. Mankrik bat darum, sie den Grimmhauern wieder abzunehmen, die sie fortgeschleppt hatten, damit er sie an ihr Denkmal legen und sie nie vergessen könne.]=],
		},
	},
	mentions = {
		{ text = "Vom Hass verzehrt" },
	},
	bonds = {
		{ id = "olgra", name = "Olgra", note = "seine Frau" },
	},
})

Translate("deDE", "olgra", {
