})

Translate("deDE", "mangletooth", {
	title = "Mangletooth",
	subtitle = "Der gefangene Stacheleber",
	found = "Ein Käfig in Camp Taurajo",
	hint = [=[Sprich mit dem Stacheleber, der in Camp Taurajo in einem Käfig gehalten wird.]=],
	allegiance = "Grimmhauer (verbannt)",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mangletooth ist ein Mystiker vom {link:razormane-quilboar}Stamm der Grimmhauer{/link}, der in einem Käfig in {link:camp-taurajo}Camp Taurajo{/link} sitzt. Er schnaubt zwischen seinen Worten, und seine Worte sind bitter. Sein Volk kehrte ihm den Rücken und ließ ihn verrotten, und er hat ihm nicht vergeben. Noch immer kennt er die Magie Agamaggans, des Ebergeistes seines Volkes, und er tauscht sie gegen Rache.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Durch Mangletooth erfuhr die {link:horde}Horde{/link}, wer die Überfälle der {link:razormane-quilboar}Grimmhauer{/link} auf {link:the-crossroads}Crossroads{/link} wirklich anführte: drei {link:quilboar}Stacheleber{/link}, die aus dem {link:razorfen-kraul}Kral von Razorfen{/link} gekommen waren.]=],
		},
		{
			title = "Taten",
			text = [=[• Er drängt zu Schlägen gegen die geistigen Anführer der {link:bristleback-quilboar}Borstennacken{/link}.
• Er nannte {link:nak}Nak{/link}, Kuz und {link:lok-orcbane}Lok Orcbane{/link} als die Anführer der Überfälle.
• Er segnet jene, die ihm Blutsplitter bringen, mit der Macht Agamaggans.]=],
		},
	},
	chapters = {
		{
			title = "Verrat von innen",
			hint = [=[Erschlage die drei Stacheleber, die die Überfälle anführen, wie Mangletooth es verlangt.]=],
			text = [=[Besser, es endet so, sagte Mangletooth, als die drei tot waren. Sie hätten sich vergewissern sollen, dass er tot war, bevor sie ihm den Rücken kehrten. Er schickte den Kopf ihres Anführers an {link:thork}Thork{/link}, wohl wissend, dass der {link:orcs}Orc{/link} nie glauben würde, dass ein {link:quilboar}Stacheleber{/link} geholfen hatte.]=],
		},
	},
	mentions = {
		{ text = "Stämme im Krieg" },
		{ text = "Verrat von innen, zu {link:thork}Thork{/link} gebracht" },
		{ text = "Blutsplitter von Agamaggan" },
		{ text = "Geist des Windes" },
		{ text = "Agamaggans Stärke" },
	},
	bonds = {
		{ id = "lok-orcbane", name = "Lok Orcbane", note = "verriet ihn" },
		{ id = "nak", name = "Nak", note = "verriet ihn" },
		{ id = "thork", name = "Thork", note = "empfängt sein Geschenk" },
	},
})

Translate("deDE", "tonga-runetotem", {
	title = "Tonga Runetotem",
	subtitle = "Druide von Crossroads",
	found = "Crossroads",
	hint = [=[Sprich mit dem Druiden der Tauren, der die Oasen des Brachlands erforscht.]=],
	allegiance = "Zirkel des Cenarius · Tauren",
	aliases = { "Tonga" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tonga Runetotem ist ein Druide der {link:tauren}Tauren{/link}, der von {link:thunder-bluff}Thunder Bluff{/link} ausgesandt wurde, um zu erfahren, welche seltsame Macht in das {link:the-barrens}Brachland{/link} sickert. Er trauert um das grüne Land, das das Brachland einst war. In den neuen Oasen fand er Spalten in der Erde und in ihren Wassern eine Macht, die Leben aus toten Samen erwecken und die Tiere verzerren kann, die davon trinken. Ihm ist, als träume das Land und könne nicht erwachen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tongas Suche war der erste Faden, der die Druiden von {link:thunder-bluff}Thunder Bluff{/link} zu den {link:wailing-caverns}Höhlen des Wehklagens{/link} führte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er fand die Spalten unter den vergessenen Teichen und der brackigen Oase.
• Er schickte die verseuchten Panzer der Schnappkiefer der Oase an {link:hamuul-runetotem}Hamuul Runetotem{/link}.
• Er braut eine Salbe für die kranken Gazellen der nördlichen Ebenen.
• Er teilt seine Erkenntnisse mit seiner Klangefährtin Mura im {link:silverpine-forest}Silberwald{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Das träumende Land",
			hint = [=[Erforsche die Oasen für Tonga und bringe ihm, was die Tiere offenbaren.]=],
			text = [=[Die toten Samen keimten im Spalt der brackigen Oase. Die Panzer der Schnappkiefer trugen einen Makel, den Tonga nie gesehen hatte. Da wusste er, dass die Wasser die Ursache waren und dass die {link:wailing-caverns}Höhlen des Wehklagens{/link} ihr Ursprung sein mussten.]=],
		},
	},
	mentions = {
		{ text = "Die Oasen des Brachlands" },
		{ text = "{link:the-forgotten-pools}Die vergessenen Teiche{/link}" },
		{ text = "{link:the-stagnant-oasis}Die brackige Oase{/link}" },
		{ text = "Veränderte Wesen" },
		{ text = "Mura Runetotem" },
		{ text = "Heilung der Kranken" },
		{ text = "Die Hauptquelle" },
	},
	bonds = {
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "schickte ihn ins Brachland" },
	},
})

Translate("deDE", "regthar-deathgate", {
	title = "Regthar Deathgate",
