	allegiance = "Horde",
	aliases = { "Regthar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Regthar Deathgate ist ein orcischer Krieger, der eine Reihe von Bunkern westlich von {link:the-crossroads}Crossroads{/link} hält. Sein Krieg gilt den {link:kolkar-centaurs}Kolkarzentauren{/link}. Einst waren sie im {link:the-barrens}Brachland{/link} verstreut und ungeordnet, doch neue Anführer haben sich erhoben, um sie zu sammeln, und Regthar will jeden dieser Anführer tot sehen. Ihre Köpfe bewahrt er zusammen auf.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Regthar ist die Antwort der {link:horde}Horde{/link} auf die {link:centaurs}Zentauren{/link}. Seine Jagd hat ihn vom {link:the-barrens}Brachland{/link} bis in das vom Krieg zerrissene Land {link:desolace}Desolace{/link} geführt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er setzte Kopfgelder auf die Häuptlinge der {link:kolkar-village}Kolkar{/link} aus: {link:barak-kodobane}Barak Kodobane{/link}, {link:verog-the-dervish}Verog{/link} den Derwisch und {link:hezrul-bloodmark}Hezrul Bloodmark{/link}.
• Er bezahlt für Zentaurenarmschienen, die Kriegern der Kolkar abgenommen wurden.
• Er wirbt Agenten für einen Einsatz gegen die {link:centaurs}Zentauren{/link} von {link:desolace}Desolace{/link} an.]=],
		},
	},
	chapters = {
		{
			title = "Gegenangriff",
			hint = "Verteidige die Bunker, wenn die Kolkar Rache nehmen wollen.",
			text = [=[Rasend über den Tod ihrer Anführer schickten die {link:kolkar-village}Kolkar{/link} eine Kriegsschar aus ihrer Heimat in {link:desolace}Desolace{/link}. Sie griff die Bunker von Westen an, angeführt von Kriegsherr Krom'zar. Als der Kriegsherr fiel, sandte Regthar {link:thrall}Thrall{/link} die Nachricht vom Sieg.]=],
		},
	},
	mentions = {
		{ text = "Anführer der {link:kolkar-village}Kolkar{/link}" },
		{ text = "{link:verog-the-dervish}Verog der Derwisch{/link}" },
		{ text = "{link:hezrul-bloodmark}Hezrul Bloodmark{/link}" },
		{ text = "Zentaurenarmschienen" },
		{ text = "Regthar Deathgate" },
	},
	bonds = {
		{ id = "barak-kodobane", name = "Barak Kodobane", note = "sein Feind" },
		{ id = "verog-the-dervish", name = "Verog der Derwisch", note = "sein Feind" },
		{ id = "hezrul-bloodmark", name = "Hezrul Bloodmark", note = "sein Feind" },
	},
})

