		{
			title = "Zusammenfassung",
			text = [=[Hauptmann Fairmount befehligt die Feste {link:northwatch-hold}Northwatch{/link} für {link:theramore-isle}Theramore{/link}. Ihre Soldaten und Kanoniere beobachten von den Mauern aus das Meer und die Ebenen. Die Goblins von {link:ratchet}Ratchet{/link} und ihre Partner nennen sie paranoid und schnell mit dem Feuer. Ihre Geschütze haben die Schiffe der Freibeuter von Thalo'dan versenkt, und ein Seemann, der einen solchen Untergang überlebte, wurde als Bedrohung für die {link:alliance}Allianz{/link} in ihre Zellen gesperrt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Fairmount hält den härtesten Posten der {link:alliance}Allianz{/link} im {link:the-barrens}Brachland{/link}, an Land von der {link:horde}Horde{/link} und auf See von Piraten umgeben.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie befehligt die Soldaten und Kanoniere der Feste {link:northwatch-hold}Northwatch{/link}.
• Ihre Geschütze haben Schiffe der Freibeuter von Thalo'dan versenkt.]=],
		},
	},
	mentions = {
		{ text = "Die Kanonen von {link:northwatch-hold}Northwatch{/link}" },
		{ text = "Befreit aus der Feste" },
	},
	bonds = {
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "die Herrscherin, der sie dient" },
	},
})

Translate("deDE", "gazrog", {
	title = "Gazrog",
	subtitle = "Hüter des Wachturms",
	found = "Crossroads, beim Wachturm",
	hint = [=[Sprich mit dem Orc, dessen Soldaten um ihren Sold bestohlen wurden.]=],
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gazrog wacht über die Wachen von {link:the-crossroads}Crossroads{/link}. Vor Kurzem wurde das Silber, mit dem sie bezahlt werden sollten, aus dem Wachturm gestohlen. Der Dieb, den man in jener Nacht erwischte, war ein Raptor, und Gazrog konnte es kaum glauben. Er will die Raptoren tot und das Silber zurück, und es kümmert ihn nicht, was ein Raptor damit wollte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gazrog sorgt dafür, dass die Soldaten von {link:the-crossroads}Crossroads{/link} bezahlt und verpflegt werden. Er behält auch jene im Blick, die fern der Heimat fallen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er setzte ein Kopfgeld auf die Raptoren des Brachlands aus.
• Er ließ einen Heiltrank für den verwundeten Grunzer Dogran holen.]=],
		},
	},
	chapters = {
		{
			title = "Das Silber der Raptoren",
			hint = [=[Finde heraus, wo die Raptoren das gestohlene Silber versteckten.]=],
			text = [=[Das Silber lag in den Nestern der {link:raptor-grounds}Raptorgründe{/link}, südlich von {link:ratchet}Ratchet{/link}. Gazrog gab zu, dass die Geschichten über die Schläue der Raptoren wahrer sein mochten, als er gedacht hatte. Die Wachen von {link:the-crossroads}Crossroads{/link} verdankten ihren Sold für den nächsten Monat dem, der es zurückbrachte.]=],
		},
	},
	mentions = {
		{ text = "Raptorendiebe" },
		{ text = "Neuigkeiten von Dogran" },
	},
	bonds = {
		{ id = "zargh", name = "Zargh", note = "versorgt dieselbe Stadt" },
	},
})

Translate("deDE", "zargh", {
