})

Translate("deDE", "jorn-skyseer", {
	title = "Jorn Skyseer",
	subtitle = "Jäger von Camp Taurajo",
	found = "Camp Taurajo",
	hint = "Sprich mit dem Jäger der Tauren in Camp Taurajo.",
	allegiance = "Tauren · Horde",
	aliases = { "Jorn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jorn Skyseer lehrt in {link:camp-taurajo}Camp Taurajo{/link} den Pfad des Jägers. Er nimmt die Schüler von {link:sergra-darkthorn}Sergra Darkthorn{/link} auf und schickt sie gegen die wildesten Bestien der Ebenen: den Raptor Ishamuhale, die Donnerechsen und die Donnerfalken. Er spricht von jeder großen Bestie mit ihrem Taurennamen, und er lehrt, dass die Stärke der Beute auf den Jäger übergeht. Seine Schwester Mahren jagt die Bestien des Meeres entlang der Küste.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Jorn ist der Hüter der Jagdüberlieferung der {link:tauren}Tauren{/link}. Als im Süden ein seltsames Insektenwesen erschlagen wurde, sah er darin ein düsteres Omen für sein Volk.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Jäger gegen Ishamuhale, den man Speerzahn nennt.
• Er ehrt jene, die Trophäen von {link:lakota-windsong}Lakota{/link}'mani, Owatanka und Washte Pawne bringen.
• Er schickt bewährte Jäger zu {link:melor-stonehoof}Melor Stonehoof{/link} nach {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
	},
	mentions = {
		{ text = "Jorn Skyseer" },
		{ text = "Ishamuhale" },
		{ text = "Wütende Donnerechsen" },
		{ text = "Der Schrei des Donnerfalken" },
		{ text = "Mahren Skyseer" },
		{ text = "{link:lakota-windsong}Lakota{/link}'mani" },
		{ text = "Owatanka" },
		{ text = "Washte Pawne" },
		{ text = "Der Ernter" },
		{ text = "{link:melor-stonehoof}Melor{/link} schickt Nachricht" },
	},
	bonds = {
		{ id = "sergra-darkthorn", name = "Sergra Darkthorn", note = "schickt ihm Schüler" },
		{ id = "melor-stonehoof", name = "Melor Stonehoof", note = "empfängt seine Besten" },
	},
})

Translate("deDE", "tatternack-steelforge", {
	title = "Tatternack Steelforge",
	subtitle = "Schmied von Camp Taurajo",
	found = "Camp Taurajo",
	hint = "Sprich mit dem Schmied von Camp Taurajo.",
	allegiance = "Horde",
	aliases = { "Tatternack" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tatternack Steelforge ist der Schmied von {link:camp-taurajo}Camp Taurajo{/link}. Er arbeitet für den Kriegshäuptling, der mit dem, was er bisher geschaffen hat, zufrieden ist. Er studiert die Waffen des Feindes, denn er hat gehört, dass die {link:razormane-quilboar}Grimmhauer{/link}, die keine geschickten Schmiede haben, irgendwie begonnen haben, stabilere Waffen herzustellen. Was er in ihren Klingen fand, beunruhigte ihn: Die {link:quilboar}Stacheleber{/link} sind weiter, als irgendjemand dachte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tatternack warnt, dass die {link:horde}Horde{/link} die {link:quilboar}Stacheleber{/link} unterschätzt haben könnte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er studiert die Waffen der Pirscher, Seher und Krieger der {link:razormane-quilboar}Grimmhauer{/link}.
• Er sucht seltsame Erze für Waffen, die des Kriegshäuptlings würdig sind.]=],
		},
	},
	mentions = {
		{ text = "Waffen der Wahl" },
		{ text = "Eine neue Erzprobe" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "der Kriegshäuptling, für den er schmiedet" },
	},
})

Translate("deDE", "baron-longshore", {
	title = "Baron Longshore",
	subtitle = "Kapitän der Heedless",
	found = "Die Piratenlager südlich von Ratchet",
	hint = [=[Stelle dich dem Piratenkapitän, der die Freibeuter südlich von Ratchet anführt.]=],
