Translate("deDE", "brewmaster-drohn", {
	title = "Braumeister Drohn",
	subtitle = "Brauer von Ratchet",
	found = "Ratchet",
	hint = [=[Suche den orcischen Brauer, der ein altes Rezept der Pandaren bewahrt.]=],
	allegiance = "Horde",
	aliases = { "Drohn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Braumeister Drohn ist ein Brauer, der alte Rezepte bewahrt. Sein Lehrmeister lernte sie von Chen Stormstout, einem wandernden Brauer, der einst mit {link:rexxar}Rexxar{/link} reiste, und gab sie an ihn weiter. Als eines von Chens leeren Fässern im {link:the-barrens}Brachland{/link} auftauchte, hatte Drohn seit einer Kodoewigkeit nichts von Chen gehört. Es weckte seine Erinnerungen, und er braute das Sturmbräu noch einmal.]=],
		},
		{
			title = "Bedeutung",
