		},
	},
	mentions = {
		{ text = "Chens leeres Fass" },
		{ text = "Chens leeres Fass, das Sturmbräu" },
		{ text = "Chens leeres Fass, das Troggbier" },
	},
})

Translate("deDE", "gann-stonespire", {
	title = "Gann Stonespire",
	subtitle = "Der Letzte der Stonespire",
	found = "Die Straße nördlich von Bael Modan",
	hint = [=[Suche den Tauren, der allein über die Straßen nahe Bael Modan wandert.]=],
	allegiance = "Stamm der Stonespire · Tauren",
	aliases = { "Gann" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gann Stonespire wandert allein über die Straßen des südlichen Brachlands. Das Land, in dem die {link:dwarves}Zwerge{/link} nun in {link:bael-modan}Bael Modan{/link} graben, war die Heimat und Ernährerin seines Stammes. Ihre Sprengungen treiben Löcher hinein, und ihre Maschinen reißen es auseinander. Gann versuchte, eine friedliche Einigung mit ihnen zu erreichen, und scheiterte. Nun sucht er ihre Tagebücher, ihre Sprengstoffe und die Zerstörung ihrer Flugmaschine.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gann ist die Stimme eines Stammes, der sein Land verlor. Er bittet darum, dass jene, die für ihn kämpfen, in {link:thunder-bluff}Thunder Bluff{/link} als Verteidiger heiligen Taurenbodens in Erinnerung bleiben.]=],
		},
		{
			title = "Taten",
			text = [=[• Er versuchte vergeblich, mit den Zwergen von {link:bael-modan}Bael Modan{/link} Frieden zu schließen.
• Er fertigte eine Sprengladung nach den eigenen Plänen der {link:dwarves}Zwerge{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Ganns Rache",
			hint = "Zerstöre die Flugmaschine von Bael Modan für Gann.",
			text = [=[Für Gann war die Flugmaschine der {link:dwarves}Zwerge{/link} mehr als ein Kriegswerkzeug. Sie war eine Beleidigung für das Andenken seines Stammes. Er baute eine Ladung nach dem Tagebuch des Prospektors der Zwerge und vertraute sie jemandem an, der sie zur Maschine tragen würde.]=],
		},
	},
	mentions = {
		{ text = "Ganns Rückforderung" },
		{ text = "Ganns Rache" },
	},
})

Translate("deDE", "walton", {
	title = "Walton",
	subtitle = "Der einsiedlerische Gerber",
	found = "Ein Grat über den trockenen Hügeln",
	hint = [=[Steige zu dem Einsiedler hinauf, der auf dem Grat über den trockenen Hügeln lebt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Walton ist ein Gerber, der allein auf einem Grat über den trockenen Hügeln lebt. Er handelt mit Häuten mit dem Jäger {link:vrang-wildgore}Vrang Wildgore{/link}, der Besucher warnt, sich von seinem Aussehen nicht erschrecken zu lassen. Walton war einst ein Seemann der Flotte von {link:kul-tiras}Kul Tiras{/link}. Als {link:daelin-proudmoore}Daelin Proudmoore{/link} Krieg gegen die {link:horde}Horde{/link} führte, wandte sich Walton gegen die Methoden des Admirals, vor allem gegen das Töten von Zivilisten. Seine Geschichte habe noch mehr, sagt er, und er erzählt sie nicht ganz.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Walton ist der Beweis, dass nicht jeder Kul Tiraner dem Admiral bereitwillig folgte. Die Männer, die noch immer Daelins Banner führen, haben ihn nicht vergessen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verließ den Dienst des Admirals wegen des Tötens von Zivilisten.
• Er gerbt die Häute, die {link:vrang-wildgore}Vrang Wildgore{/link} ihm bringt.]=],
		},
	},
	chapters = {
		{
			title = "Unwillkommene Gäste",
			hint = "Steh dem Einsiedler bei, wenn Fremde den Grat heraufsteigen.",
			text = [=[Eine Schar Männer kam den Grat herauf: ein Kopfgeldjäger namens Terry Longdrink und Marinesoldaten aus {link:kul-tiras}Kul Tiras{/link}. Sie waren wegen Walton gekommen. Als der Kampf vorüber war und er noch lebte, sagte er, er habe immer gewusst, dass es ihn eines Tages einholen würde.]=],
		},
		{
			title = "Ärger im Tal",
			hint = [=[Finde heraus, warum kul-tiranische Soldaten bei der zerstörten Karawane lagern.]=],
			text = [=[Walton hatte Männer in der Livree von {link:kul-tiras}Kul Tiras{/link} gesehen, die {link:stranglethorn-vale}das Tal{/link} darunter absuchten. Die Befehle, die man in ihrem Lager fand, stammten von {link:lieutenant-benedict}Leutnant Benedict{/link} von {link:tiragarde-keep}Burg Tiragarde{/link}. Sie jagten einen Deserteur. Die Vergangenheit, sagte Walton, habe ihn endlich eingeholt.]=],
		},
	},
	mentions = {
		{ text = "Der einsiedlerische Gerber" },
	},
	bonds = {
		{ id = "vrang-wildgore", name = "Vrang Wildgore", note = "handelt mit ihm mit Häuten" },
		{ id = "daelin-proudmoore", name = "Daelin Proudmoore", note = "der Admiral, dem er trotzte" },
		{ id = "lieutenant-benedict", name = "Leutnant Benedict", note = "schickte Männer, um ihn zu finden" },
	},
})

Translate("deDE", "vrang-wildgore", {
	title = "Vrang Wildgore",
	subtitle = "Fallensteller der trockenen Hügel",
	found = "Das Tal unterhalb der trockenen Hügel",
	hint = [=[Sprich mit dem verwundeten Jäger, der im Tal unterhalb der trockenen Hügel Fallen stellt.]=],
	allegiance = "Horde",
	aliases = { "Vrang" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vrang Wildgore ist ein Jäger und Fallensteller des nördlichen Brachlands. Eine frische Wunde am Bein hat ihn unfähig gemacht, zu jagen oder zu klettern, und es kränkt seinen Stolz, Fremde um Hilfe zu bitten. Doch er hat Verpflichtungen einzuhalten. Er tauscht rohe Löwenhäute mit einem Gerber, der auf dem Grat über ihm lebt, und erhält dafür das fertige Leder seines Handwerks.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Vrang ist der einzige Freund des Einsiedlers {link:walton}Walton{/link}, und er verbürgt sich für ihn bei jedem, der fragt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelt die Häute der großen Savannenlöwen.
• Er stellt im Tal unterhalb der trockenen Hügel Fallen auf.]=],
		},
	},
	mentions = {
		{ text = "Verletzter Stolz und Löwenhäute" },
		{ text = "Der einsiedlerische Gerber" },
		{ text = "Vrangs Wild" },
	},
	bonds = {
		{ id = "walton", name = "Walton", note = "sein Handelspartner" },
	},
})

Translate("deDE", "chol-aruk", {
	title = "Chol'aruk",
	subtitle = "Der Verschlinger",
	found = "Eine Höhle auf dem Plateau des Dornenhügels",
	hint = [=[Suche den Hort der Bestie, die die Grimmhauer den Verschlinger nennen.]=],
	allegiance = "Stacheleber der Grimmhauer",
	aliases = { "Der Verschlinger" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Chol'aruk ist ein ungeheuerlicher {link:quilboar}Stacheleber{/link}, der seinen Hort in einer Höhle auf dem {link:thorn-hill}Dornenhügel{/link} hat. Die {link:razormane-quilboar}Grimmhauer{/link} nennen ihn den Verschlinger. Wer ihn gesehen hat, sagt, er sei fünfmal so groß wie ein gewöhnlicher Stacheleber, sein Blutdurst werde nie gestillt, und er könne einen {link:orcs}Orc{/link} im Ganzen verschlingen. Die meisten Leute glauben solchen Geschichten nicht. Gur'ak aus {link:the-crossroads}Crossroads{/link} glaubt sie, und ebenso Bainham, ein Soldat der {link:alliance}Allianz{/link} in {link:ratchet}Ratchet{/link}. Jeder von ihnen hat schon einmal gegen eine Bestie wie diese gekämpft, und jeder verlor Kameraden an sie.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Chol'aruk ist ein dunkles Zeichen. Sollten solche Scheusale in größerer Zahl unter den Stachelebern wandeln, wäre der Schaden, den sie dem Land zufügen könnten, schrecklich.]=],
		},
		{ title = "Taten", text = "• Er haust in den Tiefen des Dornenhügels." },
	},
	mentions = {
		{ text = "Chol'aruk der Verschlinger, für Gur'ak" },
		{ text = "Chol'aruk der Verschlinger, für Bainham" },
	},
})

Translate("deDE", "kolkar-centaurs", {
	title = "Kolkarzentauren",
	aliases = { "Kolkar", "Kolkarzentaur", "Stamm der Kolkar" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die {link:kolkar-village}Kolkar{/link} sind ein Stamm von {link:centaurs}Zentauren{/link}, die das {link:the-barrens}Brachland{/link} und die Lande ringsum durchstreifen. Ihre Reiter lagern an den Oasen, jagen die Tiere, die zum Trinken kommen, und fallen über Reisende auf den Straßen her. Sie überfielen die {link:tauren}Tauren{/link} jahrelang, bevor die {link:orcs}Orcs{/link} kamen, und seither überfallen sie die {link:horde}Horde{/link}.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Lange Zeit waren die {link:kolkar-village}Kolkar{/link} des Brachlands verstreut und ungeordnet. Nun haben sich neue Anführer unter ihnen erhoben: {link:barak-kodobane}Barak Kodobane{/link} nahe den vergessenen Teichen, {link:verog-the-dervish}Verog der Derwisch{/link} an der brackigen Oase und {link:hezrul-bloodmark}Hezrul Bloodmark{/link}, der größte von ihnen, an der blühenden Oase. Unter diesen Häuptlingen ist der Stamm zu einer wahren Bedrohung geworden. {link:regthar-deathgate}Regthar Deathgate{/link} jagt sie von seinen Bunkern westlich von {link:the-crossroads}Crossroads{/link} aus, und als ihre Anführer fielen, kam eine Kriegsschar aus der Heimat der Kolkar in {link:desolace}Desolace{/link}, um Rache zu nehmen. In {link:durotar}Durotar{/link} hält eine weitere Schar die felsige Schlucht der {link:kolkar-crag}Kolkarklippe{/link}.]=],
		},
	},
})

Translate("deDE", "razormane-quilboar", {
	title = "Grimmhauer",
	aliases = { "Stacheleber der Grimmhauer", "Stamm der Grimmhauer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Grimmhauer sind ein Stamm von {link:quilboar}Stachelebern{/link} im nördlichen und südlichen {link:the-barrens}Brachland{/link}. Sie errichten ihre Lager zwischen großen Dornenranken, die aus der Erde wachsen, und sie verehren den Ebergeist Agamaggan, aus dessen Blut die Dornen entstanden sein sollen. Bevor die {link:orcs}Orcs{/link} kamen, durchstreiften sie das Land, das heute {link:durotar}Durotar{/link} ist, und sie haben seinen Verlust nie hingenommen.]=],
		},
		{
